def solve(inputs: dict) -> float:
    # Extract parameters with flexible key names
    def find(keys, default=None):
        for k in inputs:
            kl = k.lower()
            for key in keys:
                if key in kl:
                    return inputs[k]
        return default

    start = find(['start', 'begin', 'initial', 'seed'])
    mult = find(['mult', 'multiplier', '*', 'a'])
    add = find(['add', 'increment', 'plus', 'c'])
    mod = find(['mod', 'modulus', 'm'])
    rounds = find(['round', 'iter', 'step', 'times', 'n'])

    # Fallback: if not found, try positional numeric values
    vals = [v for v in inputs.values() if isinstance(v, (int, float))]
    if start is None and len(vals) >= 1:
        start = vals[0]
    if mult is None and len(vals) >= 2:
        mult = vals[1]
    if add is None and len(vals) >= 3:
        add = vals[2]
    if mod is None and len(vals) >= 4:
        mod = vals[3]
    if rounds is None and len(vals) >= 5:
        rounds = vals[4]

    X = int(start)
    a = int(mult)
    c = int(add)
    m = int(mod)
    n = int(rounds)
    for _ in range(n):
        X = (a * X + c) % m
    return float(X)

