def solve(inputs: dict) -> float:
    # Find the two lists: moduli and remainders
    lists = [v for v in inputs.values() if isinstance(v, (list, tuple))]
    rems = None
    mods = None
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            kl = k.lower()
            if 'mod' in kl:
                mods = list(v)
            elif 'rem' in kl:
                rems = list(v)
    if mods is None or rems is None:
        # fallback: assume order rems, mods per problem text
        if len(lists) >= 2:
            rems = list(lists[0])
            mods = list(lists[1])

    def crt(rems, mods):
        from functools import reduce
        M = reduce(lambda a, b: a * b, mods, 1)
        x = 0
        for r, m in zip(rems, mods):
            Mi = M // m
            # inverse of Mi mod m
            inv = pow(Mi, -1, m)
            x += r * Mi * inv
        return x % M

    r = crt([int(a) for a in rems], [int(a) for a in mods])
    return float(r)

