def solve(inputs: dict) -> float:
    # Find matrix M, power, modulus
    M = None
    power = None
    mod = None
    for k, v in inputs.items():
        kl = k.lower()
        if isinstance(v, (list, tuple)):
            # could be matrix (list of lists) or flat
            if len(v) > 0 and isinstance(v[0], (list, tuple)):
                M = [list(row) for row in v]
            elif 'm' in kl or 'matrix' in kl:
                M = v
    # scalars
    scalars = [(k, v) for k, v in inputs.items() if isinstance(v, (int, float))]
    for k, v in scalars:
        kl = k.lower()
        if 'pow' in kl or 'exp' in kl:
            power = int(v)
        elif 'mod' in kl:
            mod = int(v)

    # If M still None, try to build from flat list of 4
    if M is None:
        for v in inputs.values():
            if isinstance(v, (list, tuple)) and len(v) == 4 and all(isinstance(x,(int,float)) for x in v):
                M = [[v[0], v[1]], [v[2], v[3]]]
    # fallback scalars
    nums = [v for k, v in scalars]
    if power is None:
        # heuristic: power smaller, mod larger
        cand = sorted(nums)
        if len(cand) >= 1:
            power = int(cand[0])
    if mod is None:
        cand = sorted(nums)
        if len(cand) >= 1:
            mod = int(cand[-1])

    n = len(M)
    mod = int(mod)
    A = [[int(M[i][j]) % mod for j in range(n)] for i in range(n)]

    def matmul(X, Y):
        return [[sum(X[i][k] * Y[k][j] for k in range(n)) % mod for j in range(n)] for i in range(n)]

    # identity
    R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    p = int(power)
    base = A
    while p > 0:
        if p & 1:
            R = matmul(R, base)
        base = matmul(base, base)
        p >>= 1

    total = sum(R[i][j] for i in range(n) for j in range(n))
    return float(total)

